'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const journeys=[[60,5,4],[65,0,6],[70,5,8],[55,0,4],[65,5,8],[70,0,6]];
let variant=OrionProgress.variant('insulation'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,a={m:1,l:1},b={m:1,l:1},step=0,choice='',tested=false,running=false,solved=false,hintDepth=0,state='ready',saveFailed=false,timer=null,epoch=0;
function challenge(v=variant,s=stage){const [start,ambient,duration]=journeys[v];return{start,ambient,duration:duration+s,kind:s,target:Math.floor(ambient+(start-ambient)*Math.exp(-(duration+s)/8))};}
function temperature(m,l,time,q=challenge()){return q.ambient+(q.start-q.ambient)*Math.exp(-time/(2+[0,2,4][m]*l));}
function fair(q=challenge()){return q.kind===0?a.m>0&&b.m>0&&a.m!==b.m&&a.l===b.l:q.kind===1?a.m>0&&a.m===b.m&&a.l!==b.l:a.m===0&&b.m>0;}
function comparison(){const q=challenge(),d=temperature(a.m,a.l,q.duration)-temperature(b.m,b.l,q.duration);return Math.abs(d)<1e-8?'equal':d>0?'a':'b';}
function stopRun(){epoch++;if(timer!==null)clearTimeout(timer);timer=null;running=false;}
function resetTrial(){stopRun();a={m:stage===2?0:1,l:1};b={m:1,l:1};step=0;choice='';tested=false;solved=false;hintDepth=0;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('insulation')){variant=v;stage=0;resetTrial();}
function adjust(side,key,value){if(solved||running||!['a','b'].includes(side)||!['m','l'].includes(key)||!Number.isInteger(value)||value<(key==='m'?0:1)||value>(key==='m'?2:3))return;const c=side==='a'?a:b;if(c[key]===value)return;c[key]=value;step=0;tested=false;choice='';state='ready';render();}
function choose(c){if(solved||running||!['a','b','equal'].includes(c))return;choice=c;state='ready';render();}
function run(){if(solved||running)return;if(!fair()){state='fair';render();return;}stopRun();step=0;tested=false;choice='';state='ready';running=true;const token=epoch;const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;function tick(){if(token!==epoch)return;step++;if(step===20){tested=true;running=false;timer=null;render();return;}render();if(reduced)tick();else timer=setTimeout(tick,100);}tick();}
function check(){if(solved||running)return;const q=challenge();if(!fair())state='fair';else if(!tested)state='test';else if(!choice)state='choose';else if(choice!==comparison())state='compare';else if(stage===2&&temperature(b.m,b.l,q.duration)<q.target)state='cold';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('warmth');}render();if(solved&&stage<2)$('next').focus();}
function hints(){return[t('Keep the lanterns, starting temperature, surroundings and time the same. Change only the property named in this passage.','保持晶燈、起始溫度、環境和時間相同。只改變這段路要求的性質。'),t('Compare the final temperatures. The warmer lantern lost less heat. More insulation slows cooling; it never adds heat.','比較最後溫度。較暖的一盞流失較少熱。加強隔熱減慢冷卻，不會增加熱。'),stage===0?t('Try woven A and air-pocket B with one layer each. Run the test and read the temperatures.','試試 A 編織外套、B 氣袋外套，各一層。測試後讀取溫度。'):stage===1?t('Try the same air-pocket jacket on both: A one layer, B two layers.','兩盞都用氣袋外套：A 一層，B 兩層。'):t('Keep A unwrapped. Try two air-pocket layers on B, run, and compare.','A 不包外套。B 試用兩層氣袋外套，測試後比較。')];}
function lantern(c,x,label){const q=challenge(),temp=temperature(c.m,c.l,q.duration*step/20),wrap=c.m?`<rect x="${x-42-c.l*3}" y="75" width="${84+c.l*6}" height="67" rx="14" fill="${c.m===1?'#9f7e62':'#6d9f9f'}" stroke="#e1d0a4" stroke-width="${c.l*3}"/>`:'';return `<text x="${x}" y="25" text-anchor="middle" fill="#f5d38b" font-size="20">${label}</text><path d="M${x-18} 55V42Q${x} 22 ${x+18} 42V55" fill="none" stroke="#d2b578" stroke-width="5"/>${wrap}<rect x="${x-30}" y="55" width="60" height="98" rx="10" fill="#183c4c" stroke="#e1bd77" stroke-width="4"/><path d="M${x} 70L${x+20} 105L${x} 137L${x-20} 105Z" fill="#ffcc75" opacity="${.35+.65*(temp-q.ambient)/(q.start-q.ambient)}"/><text x="${x}" y="180" text-anchor="middle" fill="#f7ead1" font-size="18">${temp.toFixed(1)} °C</text>`;}
function chart(){const q=challenge(),y=T=>140-(T-q.ambient)/(q.start-q.ambient)*110;let lines='';for(const [c,col,dash] of [[a,'#f2cc80',''],[b,'#85d9ec','stroke-dasharray="7 4"']]){let d='';for(let i=0;i<=step;i++)d+=`${i?'L':'M'}${40+i*14} ${y(temperature(c.m,c.l,q.duration*i/20))} `;lines+=`<path d="${d}" fill="none" stroke="${col}" stroke-width="3" ${dash}/>`;}return `<svg viewBox="0 0 360 170" aria-hidden="true"><text x="170" y="15" fill="#f2cc80" font-size="14">A ━</text><text x="250" y="15" fill="#85d9ec" font-size="14">B ┄</text><path d="M40 15V140H330" stroke="#9ab8b7" fill="none"/><text x="2" y="30" fill="#dce8e1" font-size="12">${q.start}°</text><text x="2" y="143" fill="#dce8e1" font-size="12">${q.ambient}°</text><text x="40" y="163" fill="#dce8e1" font-size="12">0</text><text x="250" y="163" fill="#dce8e1" font-size="12">${q.duration} ${t('model min','模擬分鐘')}</text>${lines}</svg>`;}
function render(){const q=challenge(),complete=solved&&stage===2,progress=stage+Number(solved),elapsed=q.duration*step/20,ta=temperature(a.m,a.l,elapsed),tb=temperature(b.m,b.l,elapsed);window.OrionDiscovery?.update(complete);document.title=t('The Winter Lantern · Orion','寒冬之燈 · Orion');$('stageTitle').textContent=t(`Passage ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 段雪路 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Warmth seals · ${progress} / 3`,`暖光封印 · ${progress} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<progress?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);$('lanterns').innerHTML=`<svg viewBox="0 0 400 190" aria-hidden="true">${lantern(a,110,'A')}${lantern(b,290,'B')}</svg>`;$('lanterns').setAttribute('aria-label',t(`Two identical lanterns. A ${ta.toFixed(1)} degrees, B ${tb.toFixed(1)} degrees.`,`兩盞相同晶燈。A ${ta.toFixed(1)} 度，B ${tb.toFixed(1)} 度。`));for(const [id,c] of [['a',a],['b',b]]){$(id+'Material').value=c.m;$(id+'Layers').value=c.l;$(id+'Count').textContent=c.m?c.l:'—';$(id+'Material').disabled=solved||running;$(id+'Layers').disabled=solved||running||!c.m;}
$('conditions').textContent=t(`Both: start ${q.start} °C · air ${q.ambient} °C · ${q.duration} model minutes. Same container and contents.`,`兩盞：起始 ${q.start} °C · 氣溫 ${q.ambient} °C · ${q.duration} 模擬分鐘。容器和內容物相同。`);$('goal').textContent=stage===0?t('Compare two DIFFERENT jackets with the SAME number of layers. Which slows cooling more?','比較兩種不同外套，層數要相同。哪種較能減慢冷卻？'):stage===1?t('Compare the SAME jacket with DIFFERENT numbers of layers. Which slows cooling more?','使用相同外套，比較不同層數。哪個較能減慢冷卻？'):t(`Leave A unwrapped. Design B to finish at ${q.target} °C or warmer, then identify the warmer lantern.`,`A 不包外套。設計 B，使最後至少 ${q.target} °C，再找出較暖的晶燈。`);$('chart').innerHTML=chart();$('chart').setAttribute('aria-label',t('Cooling graph: A gold solid line, B blue dashed line. Temperatures below.','冷卻圖：A 金色實線，B 藍色虛線。下方列出溫度。'));$('reading').textContent=t(`${elapsed.toFixed(1)} / ${q.duration} model min · A ${ta.toFixed(1)} °C · B ${tb.toFixed(1)} °C`,`已過 ${elapsed.toFixed(1)} / ${q.duration} 模擬分鐘 · A ${ta.toFixed(1)} °C · B ${tb.toFixed(1)} °C`);for(const [id,c] of [['chooseA','a'],['chooseEqual','equal'],['chooseB','b']]){$(id).disabled=solved||running;$(id).setAttribute('aria-pressed',String(choice===c));}$('run').disabled=solved||running;$('stop').hidden=!running;$('check').disabled=running;
const messages={ready:['Change one thing, test, and compare the evidence.','改變一項，測試，再比較證據。'],fair:['Match the comparison rule above before testing. Keep the other conditions the same.','測試前，先符合上方的比較規則，其他條件保持相同。'],test:['Run the full test first. Stopping early does not complete the comparison.','先完成整次測試。中途停止不算完成比較。'],choose:['Choose A, B, or Equal using the final readings.','根據最後讀數，選擇 A、B 或相同。'],compare:['Read the final temperatures: which number is higher?','看看最後溫度，哪個數值較高？'],cold:['Your comparison is right, but B is below the warmth target. Improve its jacket and test again.','比較正確，但 B 未達溫度目標。改善外套再測試。'],success:['Your evidence opens another snowy passage!','你的證據打開另一段雪路！']};$('feedback').textContent=t(...messages[state]);$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('warmth')?t('Warmth Sigil saved in your collection.','暖光符印已存入收藏。'):'';}
for(const id of ['a','b']){$(id+'Material').onchange=()=>adjust(id,'m',Number($(id+'Material').value));$(id+'Layers').oninput=()=>adjust(id,'l',Number($(id+'Layers').value));}
$('chooseA').onclick=()=>choose('a');$('chooseEqual').onclick=()=>choose('equal');$('chooseB').onclick=()=>choose('b');$('run').onclick=run;$('stop').onclick=()=>{stopRun();render();};$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('aMaterial').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('insulation',variant);observedVariant=OrionProgress.variant('insulation');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('warmth');render();};function syncProgress(){const v=OrionProgress.variant('insulation'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('warmth')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);window.addEventListener('pagehide',stopRun);resetMission();OrionI18n.apply();
